class Solution {
public:
    std::string robotWithString(std::string s) {
        int n = s.size();
        std::vector<char> min_suffix(n + 1, 'z');
        for (int i = n - 1; i >= 0; i--) {
            min_suffix[i] = std::min(s[i], min_suffix[i + 1]);
        }

        std::string t;
        std::string res;
        for (int i = 0; i < n; i++) {
            t.push_back(s[i]);
            while (!t.empty() && t.back() <= min_suffix[i + 1]) {
                res.push_back(t.back());
                t.pop_back();
            }
        }
        return res;
    }
};

class Solution {
    public String robotWithString(String s) {
        int n = s.length();
        char[] minSuffix = new char[n + 1];
        minSuffix[n] = 'z';
        for (int i = n - 1; i >= 0; i--) {
            minSuffix[i] = (char) Math.min(s.charAt(i), minSuffix[i + 1]);
        }

        StringBuilder t = new StringBuilder();
        StringBuilder res = new StringBuilder();
        for (int i = 0; i < n; i++) {
            t.append(s.charAt(i));
            while (t.length() > 0 && t.charAt(t.length() - 1) <= minSuffix[i + 1]) {
                res.append(t.charAt(t.length() - 1));
                t.deleteCharAt(t.length() - 1);
            }
        }
        return res.toString();
    }
}

var robotWithString = function(s) {
    const n = s.length;
    const minSuffix = new Array(n + 1).fill('z');
    for (let i = n - 1; i >= 0; i--) {
        minSuffix[i] = s[i] < minSuffix[i + 1] ? s[i] : minSuffix[i + 1];
    }

    const t = [];
    const res = [];
    for (let i = 0; i < n; i++) {
        t.push(s[i]);
        while (t.length > 0 && t[t.length - 1] <= minSuffix[i + 1]) {
            res.push(t.pop());
        }
    }
    return res.join('');
};
